// Policy fixtures test the gate; they are not benchmark runs or production
// model/executor implementations. Live evidence is generated by evaluation.Run.
func gateFixture(t *testing.T) Evaluation {
	t.Helper()
	s, err := task.Load("../../examples/normalize-tags/task.json")
	if err != nil {
		t.Fatal(err)
	}
	s.Model = "gpt-5.4-2026-03-05"
	s.Ref = strings.Repeat("a", 40)
	s.Image = "sha256:" + strings.Repeat("b", 64)
	parent, candidate := strings.Repeat("c", 64), strings.Repeat("d", 64)
	s.Skills = []skills.Ref{{ID: "repair", Version: parent}}
	e := Evaluation{Schema: 1, ID: "policy-fixture", Status: "completed", Parent: parent, Candidate: candidate, SkillID: "repair", Repetitions: 2, MaxUSD: 2, ReservedUSD: 2, CreatedAt: time.Now()}
	for _, id := range []string{"regression", "holdout"} {
		c := FrozenCase{ID: id, Role: id, Spec: s, VerifierSHA256: strings.Repeat("e", 64)}
		e.Cases = append(e.Cases, c)
		for trial := 0; trial < 2; trial++ {
			for _, variant := range []string{"baseline", "candidate"} {
				v := parent
				if variant == "candidate" {
					v = candidate
				}
				spec := specFor(c, e.SkillID, v)
				settings, err := model.ResolveSettings(spec)
				if err != nil {
					t.Fatal(err)
				}
				p := runner.Report{RunID: strings.Repeat("f", 32), State: store.Completed, Verified: true, CleanupConfirmed: true, Model: s.Model, ModelSettings: &settings, BaseCommit: s.Ref, ImageID: s.Image, VerifierSHA256: c.VerifierSHA256, Skills: spec.Skills, InputTokens: 1000, OutputTokens: 100, VerificationAttempts: 1}
				if variant == "baseline" {
					p.InputTokens = 2000
					p.VerificationAttempts = 2
				}
				p.EstimatedUSD = settings.Price().Cost(p.InputTokens, p.OutputTokens)
				e.EstimatedUSD += p.EstimatedUSD
				e.Results = append(e.Results, Result{CaseID: id, Trial: trial, Variant: variant, Report: p})
			}
		}
	}
	return e
}

func TestPromotionGateRejectsRegressionsAndInvalidComparisons(t *testing.T) {
	e := gateFixture(t)
	if ok, reason := Gate(e); !ok {
		t.Fatal(reason)
	}
	cases := map[string]func(*Evaluation){
		"missing trial":        func(e *Evaluation) { e.Results = e.Results[:7] },
		"duplicate trial":      func(e *Evaluation) { e.Results[1] = e.Results[0] },
		"no holdout":           func(e *Evaluation) { e.Cases[1].Role = "regression" },
		"duplicate case":       func(e *Evaluation) { e.Cases[1] = e.Cases[0] },
		"pending dispatch":     func(e *Evaluation) { e.Pending = "holdout/1/candidate" },
		"billing unknown":      func(e *Evaluation) { e.Results[1].Report.BillingUnknown = true },
		"cleanup unknown":      func(e *Evaluation) { e.Results[1].Report.CleanupConfirmed = false },
		"different verifier":   func(e *Evaluation) { e.Results[1].Report.VerifierSHA256 = "different" },
		"different model":      func(e *Evaluation) { e.Results[1].Report.Model = "gpt-5.4-mini" },
		"different image":      func(e *Evaluation) { e.Results[1].Report.ImageID = "another-image" },
		"unpinned skill":       func(e *Evaluation) { e.Results[1].Report.Skills[0].Version = "" },
		"holdout failure":      func(e *Evaluation) { e.Results[7].Report.Verified = false; e.Results[7].Report.State = store.Failed },
		"regression":           func(e *Evaluation) { e.Results[1].Report.Verified = false; e.Results[1].Report.State = store.Failed },
		"false cheap estimate": func(e *Evaluation) { e.Results[1].Report.EstimatedUSD = 0 },
		"wrong total":          func(e *Evaluation) { e.EstimatedUSD = 0 },
		"no improvement": func(e *Evaluation) {
			e.EstimatedUSD = 0
			for i := range e.Results {
				p := &e.Results[i].Report
				p.InputTokens = 1000
				p.VerificationAttempts = 1
				p.EstimatedUSD = p.ModelSettings.Price().Cost(p.InputTokens, p.OutputTokens)
				e.EstimatedUSD += p.EstimatedUSD
			}
		},
		"cost regression": func(e *Evaluation) {
			e.EstimatedUSD = 0
			for i := range e.Results {
				p := &e.Results[i].Report
				if e.Results[i].Variant == "candidate" {
					p.InputTokens = 4000
				}
				p.EstimatedUSD = p.ModelSettings.Price().Cost(p.InputTokens, p.OutputTokens)
				e.EstimatedUSD += p.EstimatedUSD
			}
		},
	}
	for name, change := range cases {
		t.Run(name, func(t *testing.T) {
			b, _ := json.Marshal(e)
			var copy Evaluation
			if err := json.Unmarshal(b, &copy); err != nil {
				t.Fatal(err)
			}
			change(&copy)
			if ok, reason := Gate(copy); ok {
				t.Fatal("invalid comparison promoted", reason)
			}
		})
	}
}
